        internal static readonly Dictionary<string, string> En = new Dictionary<string, string>
        {
            ["La working copy ha {0} elementi in conflitto, mancanti, a metà o aggiunti con storia (svn copy/move, o file aggiunti da un merge non ancora committato): dopo un merge non si possono ripristinare in modo affidabile. Risolvili o committali (Changes) oppure fai Revert, poi riprova."] = "The working copy has {0} items in conflict, missing, half-done or added with history (svn copy/move, or files added by a merge not yet committed): they cannot be restored reliably after a merge. Resolve or commit them (Changes) or Revert, then try again.",
            ["Anteprima incompleta: il dry-run si è fermato alla revisione r{0}, che va in conflitto, e le successive non sono state simulate. I file di ogni revisione sono elencati qui sotto, ma i conflitti previsti arrivano solo fino a lì."] = "Incomplete preview: the dry-run stopped at revision r{0}, which runs into a conflict, and the following ones were not simulated. The files of each revision are listed below, but the predicted conflicts only go up to there.",
            ["Anteprima incompleta: il dry-run si è fermato alla prima revisione in conflitto e le successive non sono state simulate. I file di ogni revisione sono elencati qui sotto, ma i conflitti previsti arrivano solo fino a lì."] = "Incomplete preview: the dry-run stopped at the first revision in conflict and the following ones were not simulated. The files of each revision are listed below, but the predicted conflicts only go up to there.",
            ["Non ho potuto prevedere quali file il merge tocca: se ne hai modificati in comune possono esserci conflitti."] = "I could not predict which files the merge touches: if you modified files in common there may be conflicts.",
            ["Il merge non è andato a buon fine e può aver modificato dei file. Per tornare com'eri prima annulla il merge: le tue {0} modifiche pendenti vengono ripristinate dalla copia di sicurezza."] = "The merge did not succeed and may have modified some files. To go back to how you were, undo the merge: your {0} pending changes are restored from the backup copy.",
            ["La copia di sicurezza appartiene a un'altra working copy ({0}): non è stato ripristinato nulla."] = "The backup copy belongs to another working copy ({0}): nothing was restored.",
            ["{0} rifiuti o conflitti applicando la patch delle modifiche pendenti."] = "{0} rejects or conflicts applying the patch of the pending changes.",
            ["La patch delle modifiche pendenti non si è applicata: {0}"] = "The patch of the pending changes could not be applied: {0}",
            ["{0}: copia di sicurezza mancante."] = "{0}: backup copy missing.",
            ["{0}: lo stato non è tornato quello di prima del merge."] = "{0}: the status did not return to what it was before the merge.",
            ["{0}: il contenuto non è identico a quello di prima del merge."] = "{0}: the content is not identical to what it was before the merge.",
            ["Le modifiche ripristinate non coincidono del tutto con quelle di prima del merge (proprietà o contenuto)."] = "The restored changes do not fully match those from before the merge (properties or content).",
            ["Annullare il merge? Le modifiche del merge vengono tolte e le tue {0} modifiche pendenti di prima del merge vengono ripristinate (copia di sicurezza in {1}).\n\nElementi con modifiche locali ora: {2}\n\n{3}"] = "Undo the merge? The merge changes are removed and your {0} pending changes from before the merge are restored (backup copy in {1}).\n\nItems with local changes now: {2}\n\n{3}",
            ["Ripristino delle modifiche pendenti..."] = "Restoring the pending changes...",
            ["Merge annullato: le tue {0} modifiche pendenti sono state ripristinate."] = "Merge undone: your {0} pending changes have been restored.",
            ["... e altri {0} problemi."] = "... and {0} more problems.",
            ["Merge annullato, ma il ripristino delle modifiche pendenti non è verificato:\n{0}\nLe tue modifiche originali sono salvate in {1} (stato prima dell'annullamento: {2})."] = "Merge undone, but the restore of the pending changes is not verified:\n{0}\nYour original changes are saved in {1} (state before the undo: {2}).",
            ["Merge non eseguito: le modifiche pendenti non sono state toccate."] = "Merge not done: the pending changes were not touched.",
            ["Non c'è abbastanza spazio per la copia di sicurezza delle modifiche pendenti (servono {0}, liberi {1}): il merge non è partito e non è stato toccato nulla."] = "There is not enough space for the backup copy of the pending changes ({0} needed, {1} free): the merge did not start and nothing was touched.",
            ["Copia di sicurezza delle modifiche pendenti non riuscita ({0}): il merge non è partito e non è stato toccato nulla."] = "Backup copy of the pending changes failed ({0}): the merge did not start and nothing was touched.",
            ["Le tue {0} modifiche pendenti sono nella working copy insieme al merge (finiscono nello stesso commit se non scegli i file): \"Annulla merge\" le ripristina."] = "Your {0} pending changes are in the working copy together with the merge (they go in the same commit unless you choose the files): \"Undo merge\" restores them.",
            ["La working copy ha {0} elementi con modifiche non committate.\n\nIl merge verrà fatto sopra le tue modifiche. Prima ne salvo una copia di sicurezza (cartella .svn-assist\\backups della working copy): \"Annulla merge\" le ripristinerà com'erano. Se poi committi, finiscono nello stesso commit del merge (a meno che tu scelga solo alcuni file)."] = "The working copy has {0} items with uncommitted changes.\n\nThe merge will be done on top of your changes. First I save a backup copy of them (folder .svn-assist\\backups of the working copy): \"Undo merge\" will restore them as they were. If you then commit, they go in the same commit as the merge (unless you choose only some files).",
            ["ATTENZIONE: il merge tocca {0} file che hai già modificato, quindi c'è rischio di conflitti: {1}"] = "WARNING: the merge touches {0} files you have already modified, so there is a risk of conflicts: {1}",
