            ["Revert delle modifiche del merge"] = "Revert the merge changes",
            ["Update annullato"] = "Update cancelled",
            ["Merge annullato"] = "Merge cancelled",
            ["Switch a {0} annullato"] = "Switch to {0} cancelled",
            ["Il cleanup automatico non è riuscito: {0}"] = "The automatic cleanup failed: {0}",
            ["{0} dopo {1} elementi già applicati. La working copy può essere rimasta a metà o sporca: è stato eseguito un cleanup normale. Scegli come proseguire, oppure apri il Cleanup con le opzioni."] = "{0} after {1} items already applied. The working copy may be left halfway or dirty: a normal cleanup was run. Choose how to continue, or open Cleanup with options.",
            ["{0} dopo {1} elementi già applicati: restano modifiche parziali nella working copy. Puoi annullarle con un revert oppure lasciarle così."] = "{0} after {1} items already applied: partial changes remain in the working copy. You can undo them with a revert or leave them as they are.",
            ["Nessuno switch da annullare."] = "No switch to undo.",
