            ["Scegli almeno un'opzione del Cleanup."] = "Choose at least one Cleanup option.",
            ["Queste opzioni del Cleanup richiedono svn 1.9 o successivo."] = "These Cleanup options need svn 1.9 or later.",
            ["Le opzioni che eliminano file o annullano modifiche richiedono la conferma esplicita."] = "Options that delete files or revert changes need explicit confirmation.",
            ["Merge in corso..."] = "Merging...",
            ["Merge completato con {0} conflitti: vanno risolti prima di committare."] = "Merge completed with {0} conflicts: resolve them before committing.",
            ["Switch a {0} completato (revisione {1})"] = "Switched to {0} (revision {1})",
            ["Switch a {0} completato"] = "Switched to {0}",
