            ["Errore switch: {0}"] = "Error during switch: {0}",
            ["{0} (switch incompleto)"] = "{0} (incomplete switch)",
            ["Cleanup prima dello switch..."] = "Cleanup before switching...",
            ["Switch a {0} interrotto: cleanup e nuovo tentativo..."] = "Switch to {0} interrupted: cleanup and retry...",
            ["Errore: lo switch a {0} si è interrotto a metà, parte della working copy è ancora sul ramo di prima. Non fare Revert: chiudi ciò che tiene aperti i file citati da svn (es. la solution) e premi \"Completa switch\" (cleanup + switch).\n{1}"] = "Error: the switch to {0} stopped halfway, part of the working copy is still on the previous branch. Do not Revert: close whatever holds open the files svn mentions (e.g. the solution) and press \"Complete switch\" (cleanup + switch).\n{1}",
            ["Errore: lo switch a {0} non è completo. Non fare Revert: premi \"Completa switch\" (cleanup + switch)."] = "Error: the switch to {0} is not complete. Do not Revert: press \"Complete switch\" (cleanup + switch).",
            ["Nessuno switch da completare."] = "No switch to complete.",
            ["Completa switch"] = "Complete switch",
            ["Merge da {0}"] = "Merge from {0}",
            ["Lettura delle revisioni da unire..."] = "Reading the revisions to merge...",
            ["SVN Merge richiede svn 1.8 o successivo (trovato {0})."] = "SVN Merge needs svn 1.8 or later (found {0}).",
            ["Anteprima completata."] = "Preview completed.",
            ["Seleziona almeno una revisione da unire."] = "Select at least one revision to merge.",
            ["Merge da {0} in corso..."] = "Merging from {0}...",
            ["Merge {0} da {1}: rivedi le modifiche e committa, oppure annulla il merge. Messaggio del merge disponibile nei Recenti."] = "Merge {0} from {1}: review the changes and commit, or undo the merge. Merge message available in Recent.",
            ["Merge completato: {0} file in conflitto da risolvere."] = "Merge completed: {0} conflicted files to resolve.",
            ["Merge completato: rivedi le modifiche e committa."] = "Merge completed: review the changes and commit.",
            ["Merge eseguito, da committare. Conflitti da risolvere in Changes: {0}."] = "Merge done, ready to commit. Conflicts to resolve in Changes: {0}.",
            ["Merge eseguito, da committare."] = "Merge done, ready to commit.",
            ["{0} file in conflitto: risolvili nella sezione Conflitti, poi committa."] = "{0} conflicted files: resolve them in the Conflicts section, then commit.",
            ["Conflitto ad albero: non ci sono versioni da scegliere. Sistema la struttura a mano, poi segnalo come risolto."] = "Tree conflict: there are no versions to choose from. Fix the structure by hand, then mark it as resolved.",
            ["Tenere la TUA versione di \"{0}\"? Le modifiche arrivate dal server su questo file vengono scartate."] = "Keep YOUR version of \"{0}\"? The changes that came from the server on this file are discarded.",
            ["Prendere la versione LORO (del server) di \"{0}\"? Le TUE modifiche locali su questo file vengono scartate."] = "Take THEIR version (the server's) of \"{0}\"? YOUR local changes to this file are discarded.",
            ["Editor di merge aperto ({0}): salva il risultato, poi premi \"Segna come risolto\"."] = "Merge editor opened ({0}): save the result, then press \"Mark as resolved\".",
            ["Nessun editor di merge a 3 vie disponibile: aperto il file con i marcatori di conflitto (<<<<<<<, =======, >>>>>>>). Sistemalo e rimuovili, poi premi \"Segna come risolto\"."] = "No 3-way merge editor available: opened the file with the conflict markers (<<<<<<<, =======, >>>>>>>). Fix it and remove them, then press \"Mark as resolved\".",
            ["{0} (selezione di {1} revisioni)"] = "{0} ({1} selected revisions)",
            ["Nessuna revisione da unire: {0} è già allineato."] = "No revisions to merge: {0} is already up to date.",
            ["{0} revisioni da unire."] = "{0} revisions to merge.",
            ["Annullare il merge? Tutte le modifiche locali della working copy ({0} elementi) tornano allo stato di BASE.\n\n{1}\n\nL'operazione non è annullabile."] = "Undo the merge? All local changes of the working copy ({0} items) go back to BASE.\n\n{1}\n\nFiles added by the merge stay on disk as unversioned. This cannot be undone.",
            ["Annullamento del merge in corso..."] = "Undoing the merge...",
            ["Merge annullato: {0} elementi ripristinati."] = "Merge undone: {0} items restored.",
            ["La working copy è a revisioni miste: esegui SVN Update e riprova."] = "The working copy has mixed revisions: run SVN Update and try again.",
            ["\"{0}\" non è una revisione valida: scrivi un numero intero positivo (es. 1234) oppure HEAD."] = "\"{0}\" is not a valid revision: type a positive integer (e.g. 1234) or HEAD.",
            ["Cleanup in corso..."] = "Cleanup in progress...",
            ["Cleanup completato."] = "Cleanup completed.",
            ["Eliminati {0}, saltati {1} perché in uso (chiudi la soluzione o ferma il debug e riprova)."] = "Deleted {0}, skipped {1} in use (close the solution or stop debugging and retry).",
            ["Eliminati {0}."] = "Deleted {0}.",
            ["Saltato (in uso): {0}"] = "Skipped (in use): {0}",
            ["Errore cleanup: {0}"] = "Error during cleanup: {0}",
            ["Esegui Cleanup"] = "Run Cleanup",
            ["SVN Update ora"] = "SVN Update now",
            ["Operazione sconosciuta: {0}"] = "Unknown operation: {0}",
            ["Nessun elemento non versionato da aggiungere."] = "No unversioned item to add.",
            ["Aggiunta a SVN in corso..."] = "Adding to SVN...",
            ["Aggiunti a SVN: {0} elementi."] = "Added to SVN: {0} items.",
            ["Errore add: {0}"] = "Error during add: {0}",
            ["Eliminare {0} elementi?\n\n{1}\n\nI versionati ({2}) verranno rimossi da SVN al prossimo commit; i non versionati ({3}) andranno nel cestino, cartelle comprese."] = "Delete {0} items?\n\n{1}\n\nVersioned ones ({2}) will be removed from SVN at the next commit; unversioned ones ({3}) will go to the recycle bin, folders included.",
            ["Eliminati {0} elementi."] = "Deleted {0} items.",
            ["Nessun file idoneo per l'eliminazione."] = "No file suitable for deletion.",
            ["Errore: il file non si trova nella working copy."] = "Error: the file is not in the working copy.",
            ["Eliminare \"{0}\"?\n\nIl file verrà eliminato dalla cartella di lavoro e rimosso da SVN al prossimo commit."] = "Delete \"{0}\"?\n\nThe file will be deleted from the working folder and removed from SVN at the next commit.",
            ["Eliminare \"{0}\" dal disco?\n\nIl file non è versionato: verrà spostato nel cestino."] = "Delete \"{0}\" from disk?\n\nThe file is not versioned: it will be moved to the recycle bin.",
            ["ATTENZIONE: il file ha modifiche locali non committate, che andranno perse."] = "WARNING: the file has uncommitted local changes, which will be lost.",
            ["Eliminazione in corso..."] = "Deleting...",
            ["Eliminato: {0}."] = "Deleted: {0}.",
            ["Errore eliminazione: {0}"] = "Error deleting: {0}",
            ["Nessun elemento idoneo per SVN Revert."] = "No item suitable for SVN Revert.",
            [" nella cartella \"{0}\""] = " in folder \"{0}\"",
            ["Annullare le modifiche locali su {0} elementi{1}?\n\n{2}\n\nLe modifiche andranno perse e l'operazione non è annullabile."] = "Revert the local changes on {0} items{1}?\n\n{2}\n\nThe changes will be lost and the operation cannot be undone.",
            ["Revert in corso..."] = "Revert in progress...",
            ["Revert completato su {0} elementi."] = "Revert completed on {0} items.",
            ["Errore revert: {0}"] = "Error during revert: {0}",
            ["… e altri {0}"] = "... and {0} more",
            ["Seleziona un file in conflitto da risolvere."] = "Select a conflicted file to resolve.",
            ["Conflitto ad albero su \"{0}\" (rinomina/cancellazione). Sistema prima la struttura a mano, poi conferma per segnarlo come risolto."] = "Tree conflict on \"{0}\" (rename/delete). Fix the structure by hand first, then confirm to mark it as resolved.",
            ["Risoluzione conflitto in corso..."] = "Resolving the conflict...",
            ["Conflitto risolto: {0}"] = "Conflict resolved: {0}",
            ["Errore resolve: {0}"] = "Error resolving conflict: {0}",
            ["Nessun conflitto ad albero da risolvere."] = "No tree conflicts to resolve.",
            ["Segnare come risolti {0} conflitti ad albero (rinomine/cancellazioni)? Sistema prima la struttura a mano: svn non controlla nulla.\n\n{1}"] = "Mark {0} tree conflicts (renames/deletions) as resolved? Fix the structure by hand first: svn checks nothing.\n\n{1}",
            ["Risoluzione conflitti ad albero in corso..."] = "Resolving tree conflicts...",
            ["Conflitti ad albero risolti: {0}."] = "Tree conflicts resolved: {0}.",
            // 0.5.0 C/D: lock di altri, risoluzione di gruppo, marcatori al commit
            ["Bloccato da {0}"] = "Locked by {0}",
            ["Nessun conflitto di testo da risolvere."] = "No text conflicts to resolve.",
            ["\"Usa entrambe\" vale solo per i conflitti di testo."] = "\"Use both\" only applies to text conflicts.",
            ["Tenere entrambe le versioni di \"{0}\", prima la TUA poi la LORO, per ogni blocco in conflitto? Il file viene riscritto senza marcatori; controllalo prima di committare."] = "Keep both versions of \"{0}\", YOURS first then THEIRS, for every conflicting block? The file is rewritten without markers; review it before committing.",
            ["Tenere entrambe le versioni di \"{0}\", prima la LORO poi la TUA, per ogni blocco in conflitto? Il file viene riscritto senza marcatori; controllalo prima di committare."] = "Keep both versions of \"{0}\", THEIRS first then YOURS, for every conflicting block? The file is rewritten without markers; review it before committing.",
            ["Impossibile unire le due versioni di \"{0}\": non ci sono marcatori di conflitto ben formati (<<<<<<<, =======, >>>>>>>) oppure il file non è di testo. Usa l'editor di merge."] = "Cannot combine the two versions of \"{0}\": there are no well-formed conflict markers (<<<<<<<, =======, >>>>>>>) or the file is not text. Use the merge editor.",
            ["Tenere entrambe le versioni (prima la TUA poi la LORO) in {0} conflitti di testo? I file vengono riscritti senza marcatori; i file senza marcatori ben formati restano com'è. I conflitti ad albero e di proprietà non sono toccati.\n\n{1}"] = "Keep both versions (YOURS first then THEIRS) in {0} text conflicts? The files are rewritten without markers; files without well-formed markers are left as they are. Tree and property conflicts are not touched.\n\n{1}",
            ["Tenere entrambe le versioni (prima la LORO poi la TUA) in {0} conflitti di testo? I file vengono riscritti senza marcatori; i file senza marcatori ben formati restano com'è. I conflitti ad albero e di proprietà non sono toccati.\n\n{1}"] = "Keep both versions (THEIRS first then YOURS) in {0} text conflicts? The files are rewritten without markers; files without well-formed markers are left as they are. Tree and property conflicts are not touched.\n\n{1}",
            ["marcatori di conflitto assenti o non validi"] = "conflict markers missing or invalid",
            ["La cartella scelta non è dentro la working copy: il merge di una cartella parte da una cartella della working copy."] = "The chosen folder is not inside the working copy: a folder merge starts from a folder of the working copy.",
            ["La cartella \"{0}\" non esiste in {1}: manca lo stesso sottopercorso nel ramo scelto."] = "The folder \"{0}\" does not exist in {1}: the same subpath is missing in the chosen branch.",
            ["La cartella \"{0}\" non ha storia in comune con quella di {1} (nessun antenato comune): svn non può unirle."] = "The folder \"{0}\" has no history in common with the one in {1} (no common ancestor): svn cannot merge them.",
            ["svn risponde: {0}"] = "svn says: {0}",
            ["Controllo se la cartella \"{0}\" si può unire da {1}..."] = "Checking whether the folder \"{0}\" can be merged from {1}...",
            ["La cartella \"{0}\" ha {1} elementi con modifiche locali: per unire serve che sia pulita (così \"Annulla merge\" non tocca altro lavoro). Fai prima Commit oppure Revert."] = "The folder \"{0}\" has {1} items with local changes: it must be clean to merge (so \"Undo merge\" does not touch other work). Commit or Revert first.",
            ["Merge della cartella \"{0}\" da {1}: NON POSSIBILE.\n\n{2}"] = "Merge of the folder \"{0}\" from {1}: NOT POSSIBLE.\n\n{2}",
            ["Chiudi"] = "Close",
            ["Continua"] = "Continue",
            ["Merge della cartella \"{0}\" non possibile: {1}"] = "Merge of the folder \"{0}\" is not possible: {1}",
            ["Merge della cartella \"{0}\" da {1}: COMPATIBILE, ma non c'è nulla da unire (la cartella è già allineata)."] = "Merge of the folder \"{0}\" from {1}: COMPATIBLE, but there is nothing to merge (the folder is already up to date).",
            ["Nessuna revisione da unire per la cartella \"{0}\"."] = "No revisions to merge for the folder \"{0}\".",
            ["Merge della cartella \"{0}\" da {1}: COMPATIBILE.\n\n{2} revisioni da unire. Anteprima: {3} elementi toccati, {4} conflitti.\n\nIl merge riguarda solo questa cartella e svn registra le informazioni di merge (svn:mergeinfo) sulla cartella e non sulla radice del ramo. Continuare e scegliere le revisioni?"] = "Merge of the folder \"{0}\" from {1}: COMPATIBLE.\n\n{2} revisions to merge. Preview: {3} items touched, {4} conflicts.\n\nThe merge only affects this folder and svn records the merge information (svn:mergeinfo) on the folder, not on the branch root. Continue and choose the revisions?",
            ["Annullare il merge della cartella \"{2}\"? Le modifiche locali sotto questa cartella ({0} elementi) tornano allo stato di BASE; il resto della working copy non è toccato.\n\n{1}\n\nL'operazione non è annullabile."] = "Undo the merge of the folder \"{2}\"? Local changes under this folder ({0} items) go back to BASE; the rest of the working copy is not touched.\n\n{1}\n\nThis cannot be undone.",
            ["File in conflitto: scegli come risolverlo."] = "File in conflict: choose how to resolve it.",
            ["Segna come risolto"] = "Mark as resolved",
            ["Usa la mia"] = "Use mine",
            ["Usa la loro"] = "Use theirs",
            ["Usa entrambe (mia poi loro)"] = "Use both (mine then theirs)",
            ["Usa entrambe (loro poi mia)"] = "Use both (theirs then mine)",
            ["Apri editor di merge"] = "Open merge editor",
            ["Segnare come risolti {0} conflitti di testo (resolve --accept working)? Un file con ancora i marcatori di conflitto viene rifiutato.\n\n{1}"] = "Mark {0} text conflicts as resolved (resolve --accept working)? A file that still has conflict markers is rejected.\n\n{1}",
            ["Tenere la TUA versione in {0} conflitti di testo? Le modifiche arrivate dal server su questi file vengono scartate. I conflitti ad albero e di proprietà non sono toccati.\n\n{1}"] = "Keep YOUR version in {0} text conflicts? Changes that came from the server on these files are discarded. Tree and property conflicts are not touched.\n\n{1}",
            ["Prendere la versione LORO (del server) in {0} conflitti di testo? Le TUE modifiche locali su questi file vengono scartate. I conflitti ad albero e di proprietà non sono toccati.\n\n{1}"] = "Take THEIR (server) version in {0} text conflicts? Your LOCAL changes on these files are discarded. Tree and property conflicts are not touched.\n\n{1}",
            ["Risoluzione conflitti in corso..."] = "Resolving conflicts...",
            ["Conflitti di testo risolti: {0}."] = "Text conflicts resolved: {0}.",
            ["Errore resolve: {0} conflitti risolti, {1} falliti. {2}"] = "Error resolving: {0} conflicts resolved, {1} failed. {2}",
            ["Il file {0} contiene marcatori di conflitto. Committare comunque?"] = "The file {0} contains conflict markers. Commit anyway?",
            ["Commit annullato: {0} contiene marcatori di conflitto."] = "Commit cancelled: {0} contains conflict markers.",
            ["Controllo delle nuove revisioni sul server..."] = "Checking the server for new revisions...",
            ["Sul server ci sono revisioni più recenti della tua working copy (r{0}, tu sei a r{1}): qualcuno ha committato.\n\nIl commit può riuscire, ma la tua copia locale NON avrà le loro modifiche: una build o una consegna fatta da qui le perderebbe.\n\nConsigliato: SVN Update, poi commit."] = "The server has newer revisions than your working copy (r{0}, you are at r{1}): someone has committed.\n\nThe commit may succeed, but your local copy will NOT have their changes: a build or delivery made from here would miss them.\n\nRecommended: SVN Update, then commit.",
            ["Committa comunque"] = "Commit anyway",
            ["\"{0}\" è identico alla versione di partenza: non contiene né le tue modifiche né quelle in arrivo (succede togliendo la spunta nell'editor di merge di VS). Segnare comunque come risolto?"] = "\"{0}\" is identical to the starting version: it contains neither your changes nor the incoming ones (this happens when you uncheck a line in the VS merge editor). Mark as resolved anyway?",
            ["Commit annullato: fai SVN Update, controlla e poi committa."] = "Commit cancelled: run SVN Update, check, then commit.",
            ["ATTENZIONE: altri hanno committato sul ramo e la tua working copy non ha le loro modifiche. Fai SVN Update prima di compilare o consegnare."] = "WARNING: others have committed on the branch and your working copy does not have their changes. Run SVN Update before building or delivering.",
            ["Errore resolve: {0} conflitti ad albero risolti, {1} falliti. {2}"] = "Error resolving: {0} tree conflicts resolved, {1} failed. {2}",
            ["Add to Ignore List è disponibile solo per elementi non versionati."] = "Add to Ignore List is only available for unversioned items.",
            ["Aggiungere {0} elementi non versionati alla ignore list (svn:ignore) delle rispettive cartelle?\n\n{1}"] = "Add {0} unversioned items to the ignore list (svn:ignore) of their folders?\n\n{1}",
            ["Aggiornamento ignore list in corso..."] = "Updating the ignore list...",
            ["Aggiunti alla ignore list: {0} elementi."] = "Added to the ignore list: {0} items.",
            ["Errore ignore list: {0}"] = "Error updating the ignore list: {0}",
            ["Seleziona un file modificato non ancora bloccato."] = "Select a modified file that is not locked yet.",
            ["Blocca \"{0}\" (svn lock). Messaggio facoltativo:"] = "Lock \"{0}\" (svn lock). Optional message:",
            ["Messaggio"] = "Message",
            ["Lock in corso..."] = "Locking...",
            ["\"{0}\" è già bloccato da un altro utente.\n\n{1}\n\nRubare il lock lo toglie a lui: potrebbe perdere il diritto di committare il file. Procedere?"] = "\"{0}\" is already locked by another user.\n\n{1}\n\nStealing the lock takes it away from them: they may lose the right to commit the file. Proceed?",
            ["Lock non preso: il file è bloccato da un altro utente."] = "Lock not taken: the file is locked by another user.",
            ["Bloccato (lock): {0}"] = "Locked: {0}",
            ["Errore lock: {0}"] = "Error during lock: {0}",
            ["Seleziona un file bloccato da te."] = "Select a file locked by you.",
            ["Unlock in corso..."] = "Unlocking...",
            ["Sbloccato (unlock) completato: {0}"] = "Unlock completed: {0}",
            ["Errore unlock: {0}"] = "Error during unlock: {0}",
            ["Il file non è versionato: non c'è nessun diff."] = "The file is not versioned: there is no diff.",
            ["Seleziona un file versionato per vedere il diff."] = "Select a versioned file to see the diff.",
            ["Diff aperto: {0}"] = "Diff opened: {0}",
            ["Esporto {0} alla revisione r{1}..."] = "Exporting {0} at revision r{1}...",
